resultats = {}
erreurs = []
for nom in allergenes:
    try:
        s = resume_numerique(nom, condition=f"{nom}>=0.3")
        m = re.search(r":\s*(\d[\d\s\u00a0\u202f]*) patients", s)
        if m:
            resultats[nom] = int(re.sub(r"\D", "", m.group(1)))
        else:
            erreurs.append(nom)
    except Exception as e:
        erreurs.append(nom)
classement = sorted(resultats.items(), key=lambda x: x[1], reverse=True)
print(classement[:6])
print("sans résultat :", erreurs[:20], len(erreurs))

